  orochimaru: N("Orochimaru", "The Snake Sannin", 92, 46, "Wind", "Has died several times as a matter of scheduling.", [["Edo Tensei", 1.3, "nin"], ["Eight Branches Attack", 1.25, "tai"], ["Shed Skin", 0, "buff"]], "Edo Tensei"),
  hanzo: N("Hanzo of the Salamander", "Lord of Amegakure", 90, 44, "Fire", "Named the Sannin after failing to kill all three.", [["Poison Mist", 1.2, "nin"], ["Summoning: Ibuse", 1.3, "nin"], ["Kusarigama Sweep", 1.15, "tai"]], "Poison Mist"),
