  haku: N("Haku", "The Boy in the Mask", 76, 40, "Ice Release", "Ice mirrors, senbon, and a boy who does not want to kill you and will if he has to.", [["Ice Style: Demonic Mirrors", 1.3, "nin"], ["Ice Style: Thousand Needles", 1.2, "nin"], ["Thousand Flying Water Needles", 1.15, "nin"]], "Ice Style: Demonic Mirrors"),
  zabuza: N("Zabuza Momochi", "Demon of the Hidden Mist", 78, 44, "Water", "Killed his entire graduating class before he was old enough to enrol.", [["Silent Killing", 1.35, "tai"], ["Hiding in Mist", 0, "buff"], ["Water Style: Water Dragon Bullet", 1.2, "nin"]], "Silent Killing"),
