  gaara: N("Gaara", "Fifth Kazekage", 88, 40, "Magnet Release", "The sand moves before he decides to move it.", [["Magnet Style: Sand Burial", 1.35, "nin"], ["Sand Shield", 0, "guard"], ["Sand Tsunami", 1.2, "nin"]], "Magnet Style: Sand Burial"),
  neji: N("Neji Hyuga", "Hyuga prodigy", 72, 46, null, "Sees all 361 points and intends to close 64 of them.", [["Eight Trigrams Sixty-Four Palms", 1.35, "tai"], ["Eight Trigrams Palm Rotation", 0, "guard"], ["Gentle Fist", 1.15, "tai"]], "Eight Trigrams Sixty-Four Palms"),
  lee: N("Rock Lee", "The hard worker", 70, 50, null, "No ninjutsu at all. Still might be faster than you.", [["Front Lotus", 1.35, "tai"], ["Gate of Life", 0, "buff"], ["Leaf Whirlwind", 1.15, "tai"]], "Front Lotus"),
  shikamaru: N("Shikamaru Nara", "Two hundred IQ", 68, 40, null, "Has already run this fight two hundred moves ahead.", [["Shadow Possession", 1.1, "gen"], ["Shadow Strangle", 1.3, "gen"], ["Trap Setup", 0, "buff"]], "Shadow Possession"),
  kabuto: N("Kabuto Yakushi", "Snake sage", 90, 46, "Wind", "Rebuilt himself out of every bloodline he could steal.", [["Edo Tensei", 1.3, "nin"], ["Chakra Scalpel", 1.25, "tai"], ["Sage Mode", 0, "buff"]], "Edo Tensei"),
  obito: N("Obito Uchiha", "The masked man", 98, 56, "Fire", "Started the war. Intends to end the world with it.", [["Kamui Phase", 0, "guard"], ["Truth-Seeking Orbs", 1.35, "nin"], ["Ten-Tails Chakra Blast", 1.4, "nin"]], "Truth-Seeking Orbs"),
  madaraRe: N("Madara Uchiha", "Reanimated", 102, 54, "Fire", "Brought back against his will and delighted about it anyway.", [["Susanoo: Yasaka Beads", 1.35, "nin"], ["Wood Style: True Thousand Hands", 1.3, "nin"], ["Perfect Susanoo", 0, "guard"]], "Susanoo: Yasaka Beads"),
