  narutoAdult: N("Naruto Uzumaki", "Seventh Hokage", 100, 56, "Wind", "Older, tireder, and still the strongest thing in the room.", [["Baryon Mode", 0, "buff"], ["Tailed Beast Rasenshuriken", 1.4, "nin"], ["Six Paths Sage Mode", 0, "buff"]], "Baryon Mode"),
  sasukeAdult: N("Sasuke Uchiha", "The shadow Hokage", 99, 56, "Lightning", "Walks the borders so nobody else has to.", [["Susanoo: Yasaka Beads", 1.4, "nin"], ["Amaterasu", 1.3, "nin"], ["Rinnegan Shift", 0, "guard"]], "Susanoo: Yasaka Beads"),
