/* reverse lookup — a student's name to whichever NAMED entry it belongs to, if any.
   a canon figure already has a real death year and a real history tracked elsewhere;
   nothing that only knows how to make up genin fates should be allowed near them. */
const NAMED_ID_BY_NAME = {};
Object.entries(NAMED).forEach(([id, v]) => { NAMED_ID_BY_NAME[v.name] = id; });

const ERA_RESERVE = {
  warring: ["tajima", "kawarama", "toka", "izuna", "butsuma"],
  founding: ["secondRaikage", "byakuren", "toka", "mito", "hiruzen", "danzo", "onoki"],
  sannin: ["sakumo", "onoki", "minato", "ay", "killerb", "rasa", "kushina", "mito", "pakura", "tsume"],
  third: ["hiruzen", "jiraiya", "tsunade", "orochimaru", "danzo", "chiyo", "onoki", "rasa", "kushina", "shizune", "mabui", "pakura"],
  naruto: ["tsunade", "jiraiya", "orochimaru", "hiruzen", "onoki", "ay", "killerb", "danzo", "kimimaro", "zabuza", "chiyo", "rasa", "mei", "kurotsuchi", "yugito", "mabui", "tsume", "yugao"],
  boruto: ["isshiki", "code", "eida", "urashiki", "kawaki", "gaara", "kakashi", "narutoAdult", "shizune", "mei", "kurotsuchi", "tenten"],
};
const NAMED_ERA = {};
ERAS.forEach((e, i) => {
  [].concat(e.roster || [], ERA_RESERVE[e.id] || [], e.bosses || []).forEach((id) => { if (NAMED_ERA[id] === undefined) NAMED_ERA[id] = i; });
});
const eraIndex = (c) => ERAS.findIndex((e) => e.id === c.era);

function newsItem(c, txt, cat, big) {
  if (!c.news) c.news = [];
  if (c.news.some((n) => n.txt === txt)) return;
  c.news.unshift({ age: c.age, year: c.year, txt, cat: cat || "THE VILLAGES", big: !!big });
  if (c.news.length > 160) c.news.pop();
  /* anything big enough for the front page is big enough for the Chronicle */
  if (big && c.year) chron(c, { txt, cat: CHRON_CAT[cat] || "villages", big: true, line: c.name && txt.includes(c.name) ? c.name : null });
}

/* ---------- nobody dies twice, nothing breaks twice ---------- */
const folkDead = (c, name) => (c.deadFolk || []).includes(name);
function killFolk(c, name) {
  if (!name) return false;
  if (!c.deadFolk) c.deadFolk = [];
  if (c.deadFolk.includes(name)) return false;
  c.deadFolk.push(name);
  return true;
}
function freshName(c, clan) {
  if (!c) return clan ? givenName(roll(50) ? "m" : "f") + " " + clan : randName(roll(50) ? "m" : "f");
  if (!c.usedNames) c.usedNames = [];
  for (let i = 0; i < 30; i++) {
    const n = (clan ? givenName(roll(50) ? "m" : "f") + " " + clan : randName(roll(50) ? "m" : "f"));
    if (!c.usedNames.includes(n) && !folkDead(c, n)) { c.usedNames.push(n); return n; }
  }
  return clan ? givenName(roll(50) ? "m" : "f") + " " + clan : randName(roll(50) ? "m" : "f");
}
function setClanHead(c, clan, name) {
  if (!c.clanHeads) c.clanHeads = {};
  c.clanHeads[clan] = name || freshName(c, clan);
  return c.clanHeads[clan];
}
const clanGone = (c, clan) => (c.extinct || []).includes(clan) || (c.broken || []).includes(clan);
/* the one place a clan is ever broken. returns false if it was already broken or already extinct */
function breakClan(c, clan, txt, cat) {
  if (!clan || clan === "Civilian-born") return false;
  if (!c.broken) c.broken = [];
  if (!c.extinct) c.extinct = [];
  if (clanGone(c, clan)) return false;
  c.broken.push(clan);
  setClanHead(c, clan);
  if (txt) newsItem(c, txt, cat || "OBITUARIES", true);
  return true;
}
/* kill named members off a clan's roll and return who died */
function killClanFolk(c, clan, n) {
  const out = [];
  const roster = c.clanMembers && c.clanMembers[clan];
  if (roster) {
    const live = roster.filter((m) => m.alive && m.role !== "Clan Head");
    for (let i = 0; i < n && live.length; i++) {
      const idx = R(live.length);
      const m = live[idx]; live.splice(idx, 1);
      m.alive = false; killFolk(c, m.name); out.push(m.name);
    }
  }
  while (out.length < n) { const nm = freshName(c, clan); killFolk(c, nm); out.push(nm); }
  return out;
}
function killNamed(c, id, L, how, claimVid) {
  if (!id || !NAMED[id] || c.dead.includes(id) || isPlayerNamed(c, id)) return;
  c.dead.push(id);
  c.roster = c.roster.filter((x) => x !== id);
  c.reanimated = (c.reanimated || []).filter((x) => x !== id);
  newsItem(c, NAMED[id].name + ", " + namedTitle(c, id) + ", " + how + ".", "OBITUARIES", NAMED[id].lvl >= 88);
  VILLAGES.forEach((v) => {
    const ln = c.line && c.line[v.id];
    if (ln && ln.current && ln.current.id === id) {
      /* if you are taking this seat yourself, the village does not get to name anyone else */
      if (claimVid === v.id) return;
      const kt = c.kages[v.id] ? c.kages[v.id].title : "Kage";
      const root = chron(c, { cat: "deaths", big: true, kind: "kage", txt: NAMED[id].name + ", " + kt + " of " + v.name + ", " + how + "." });
      c.lastKageDeath = { id, vid: v.id, name: NAMED[id].name, title: kt, root, year: c.year };
      echo(c, "kageMemory", 20, { vid: v.id, name: NAMED[id].name, root });
      echo(c, "kageHistorians", 50, { vid: v.id, name: NAMED[id].name, root });
      /* the one way a seat changes hands: through the line, with the next holder
         checked for being alive, of their era and old enough. this used to take
         the next name off the queue blind, which is how Gaara became Kazekage at 7. */
      const nw = handOverSeat(c, v.id, { why: "died in office" });
      if (nw) newsItem(c, nw.name + " has taken the hat as " + nw.title + " of " + v.name + ".", "THE VILLAGES", true);
    } else if (c.kages[v.id] && c.kages[v.id].named === id) {
      c.kages[v.id] = { named: null, name: randName(Math.random() < 0.5 ? "m" : "f"), title: c.kages[v.id].title };
    }
  });
  const res = (ERA_RESERVE[c.era] || []).filter((x) => !c.dead.includes(x) && !c.roster.includes(x) && !isPlayerNamed(c, x));
  if (res.length) {
    const r = pick(res);
    c.roster.push(r);
    newsItem(c, NAMED[r].name + ", " + namedTitle(c, r) + ", has been entered into the Bingo Book among the strongest alive.", "BINGO BOOK");
  }
}
/* the difference between a kill and a kill that MATTERS. call right after killNamed(), only for a
   kill the player actually delivered — never for ambient/background deaths. id must still resolve
   in NAMED (killNamed does not delete the entry, only marks it dead, so this is always safe after it). */
function killFeat(c, L, id) {
  if (!id || !NAMED[id]) return;
  const n = NAMED[id];
  const tier = n.lvl >= 95 ? 4 : n.lvl >= 85 ? 3 : n.lvl >= 70 ? 2 : 1;
  const bonusRyo = Math.round(n.lvl * n.lvl * 35);
  c.ryo += bonusRyo;
  const rep = Math.round(6 + n.lvl * 0.4);
  if (c.rogue) c.infamy = cl(c.infamy + rep); else c.standing = cl(c.standing + Math.round(rep * 0.7));
  addTitle(c, "Killed " + n.name);
  c.legendaryKills = (c.legendaryKills || []).concat([id]);
  const count = c.legendaryKills.length;
  const tierLine = tier === 4
    ? n.name + " is dead. There has not been a kill like this in a generation, and every history from here treats it as a hinge point."
    : tier === 3 ? n.name + " is dead by your hand. The Bingo Book is already being reprinted."
    : tier === 2 ? n.name + " is dead. That name meant something, and you are the reason it is past tense now."
    : n.name + " is dead. One more name off the list that matters.";
  P(L, tierLine + " +" + money(bonusRyo) + ".", "e");
  newsItem(c, c.name + " has killed " + n.name + ", " + namedTitle(c, id) + ".", "OBITUARIES", n.lvl >= 80);
  const milestone = count === 1 ? "First Kill of Note" : count === 5 ? "Executioner" : count === 10 ? "Death Incarnate" : count === 20 ? "The Reaper Made Flesh" : null;
  if (milestone) { addTitle(c, milestone); newsItem(c, c.name + " has now killed " + count + " names the Bingo Book tracked. " + milestone + ".", "BINGO BOOK", count >= 10); }
  c.killFlash = { name: n.name, title: namedTitle(c, id), tier, count, ryo: bonusRyo };
  /* what happened, and what the world was told */
  const secret = (c.rogue || c.anbu) && roll(50);
  const kd = c.lastKageDeath && c.lastKageDeath.id === id && c.lastKageDeath.year === c.year ? c.lastKageDeath : null;
  if (kd || n.lvl >= 85) {
    const eid = kd ? kd.root : chron(c, { cat: "deaths", big: true, txt: n.name + ", " + namedTitle(c, id) + ", is killed." });
    const x = chronById(c, eid);
    if (x) {
      x.line = c.name;
      if (secret) { x.truth = c.name + " killed " + n.name; x.reported = "an unknown shinobi killed " + n.name; x.revealed = false; echo(c, "truth", rr(8, 30), { entry: eid }); }
      else x.txt = x.txt.replace(/\.$/, "") + ", by the hand of " + c.name + ".";
    }
    (c.echoes || []).forEach((e) => { if (kd && e.root === kd.root) e.killer = c.name; });
    if (kd) echo(c, "kageTension", 10, { vid: kd.vid, name: kd.name, root: kd.root, killer: c.name, killerVid: c.rogue ? null : c.village });
  }
}

/* every named shinobi's signature must be a real, usable technique */
(function registerSignatures() {
  Object.values(NAMED).forEach((n) => {
    if (!n.sig || MOVES[n.sig]) return;
    const row = n.moves.find((m) => m[0] === n.sig);
    const raw = row ? row[2] : "nin";
    const kind = raw === "guard" || raw === "buff" ? "buff" : raw;
    const tier = n.lvl >= 95 ? 5 : n.lvl >= 80 ? 4 : 3;
    MOVES[n.sig] = {
      name: n.sig, tier, kind, nature: n.nature || null,
      pow: kind === "buff" ? 0 : Math.round(12 + tier * 15 + Math.max(0, n.lvl - 80) * 0.9),
      cost: kind === "buff" ? 22 : 4 + tier * 7,
      eff: kind === "buff" ? (raw === "guard" ? "def" : "atk") : undefined,
    };
  });
})();


