/* ============================ THE VILLAGE ============================ */
const ORDINALS = ["First", "Second", "Third", "Fourth", "Fifth", "Sixth", "Seventh", "Eighth", "Ninth", "Tenth", "Eleventh", "Twelfth"];
const COUNCIL_ROLES = ["War Chief", "Head of Intelligence", "Academy Head", "Medical Director", "Clan Elder"];
const COUNCIL_STANCE = ["hawkish", "cautious", "traditionalist", "reformist", "opportunist", "loyalist"];

const DECREES = [
  { id: "borders", n: "Open the Borders", d: "Foreign merchants, foreign money, foreign eyes.", e: { prosperity: 18, defense: -10 }, t: "Trade income up, walls thinner." },
  { id: "conscript", n: "General Conscription", d: "Every able body of fighting age is called up.", e: { shinobi: 250, morale: -14, defense: 12 }, t: "More shinobi, unhappier ones." },
  { id: "isolate", n: "Close the Country", d: "Nobody in, nobody out, nothing gets past the gate.", e: { defense: 20, prosperity: -14 }, t: "Very safe, very poor." },
  { id: "registry", n: "Bloodline Registry", d: "Every kekkei genkai in the village catalogued and on call.", e: { defense: 12, morale: -12 }, t: "Stronger forces, resentful clans." },
  { id: "academy", n: "Academy Reform", d: "Longer training, higher standards, fewer children buried.", e: { morale: 12, shinobi: 120 }, t: "Better shinobi and they know it." },
  { id: "root", n: "Found the Root Division", d: "A branch that answers only to you and keeps no records.", e: { defense: 14, morale: -16 }, t: "Total control, quietly hated.", dark: true },
  { id: "works", n: "Public Works", d: "Roads, aqueducts, a hospital that is not a tent.", e: { morale: 16, prosperity: 12 }, cost: 250000, t: "Expensive and universally popular." },
  { id: "tax", n: "Raise the Levy", d: "The daimyo will be pleased. Nobody else will be.", e: { prosperity: -6, morale: -12 }, gold: 400000, t: "Immediate money, lasting resentment." },
];

const VILLAGE_EVENTS = [
  { c: (v) => v.prosperity > 60, f: (v, c, L) => { const g = rr(60000, 180000); v.treasury += g; P(L, "A good trading year. The treasury took in " + money(g) + ".", "g"); } },
  { c: (v) => v.prosperity < 45, f: (v, c, L) => { v.morale = cl(v.morale - rr(5, 12)); P(L, "A bad harvest in the outer districts. People are hungry and saying so.", "b"); } },
  { c: () => true, f: (v, c, L) => { v.morale = cl(v.morale + rr(6, 14)); P(L, "The village festival ran three days. Morale is up and the treasury is not.", "g"); v.treasury = Math.max(0, v.treasury - 40000); } },
  { c: () => true, f: (v, c, L) => { v.shinobi -= rr(10, 40); P(L, "A squad did not come back from the border. Names were read out at the memorial stone.", "b"); v.morale = cl(v.morale - rr(3, 8)); } },
  { c: () => true, f: (v, c, L) => { P(L, "Counter-intelligence caught a foreign agent inside the Academy. They had been there two years.", "b"); v.defense = cl(v.defense - rr(3, 9)); } },
  { c: () => true, f: (v, c, L) => { const t = rr(80000, 250000); v.treasury = Math.max(0, v.treasury - t); P(L, "The daimyo demanded tribute and framed it as a gift. " + money(t) + " left the treasury.", "b"); } },
  { c: () => true, f: (v, c, L) => { v.shinobi += rr(30, 90); v.morale = cl(v.morale + 4); P(L, "A strong graduating class. " + v.shinobi + " active shinobi on the rolls now.", "g"); } },
  { c: () => true, f: (v, c, L) => { P(L, "Two clans took a land dispute to the council and neither accepted the ruling.", "b"); v.morale = cl(v.morale - rr(4, 10)); } },
  { c: (v) => v.morale < 45, f: (v, c, L) => { v.shinobi -= rr(20, 60); P(L, "Desertions. Not many, but more than last year, and they were not the worst of your people.", "b"); } },
  { c: () => true, f: (v, c, L) => { P(L, "A child was born in the outer district with a bloodline nobody in the family has. The registry has flagged it.", "e"); } },
];

const CLAN_ROLES = [["Clan Head", 1], ["War Captain", 2], ["Warrior", 6], ["Blooded", 3], ["Untested", 3]];
/* The Otsutsuki are not a house with a compound and a ladder. There is no
   roll of them, no elders to impress, no War Captains — there are a handful of
   them in the whole of creation and most are already dead or sealed. Inventing
   fifteen relatives called Taro Otsutsuki and grading them Untested made the
   rarest bloodline in the game read like any other village family. */
const CELESTIAL = "Otsutsuki";
const isCelestialClan = (c) => c && c.clan === CELESTIAL;
function buildClanMembers(clan) {
  if (!clan || clan === "Civilian-born" || clan === CELESTIAL) return [];
  const out = []; const taken = [];
  CLAN_ROLES.forEach(([role, n]) => {
    for (let i = 0; i < n; i++) {
      const g = Math.random() < 0.5 ? "m" : "f";
      const gn = givenName(g, taken); taken.push(gn);
      out.push({
        name: gn + " " + clan, role, gender: g, alive: true,
        pw: role === "Clan Head" ? rr(55, 80) : role === "War Captain" ? rr(40, 60) : role === "Warrior" ? rr(25, 45) : role === "Blooded" ? rr(12, 26) : rr(4, 12),
        age: role === "Untested" ? rr(6, 11) : role === "Blooded" ? rr(12, 16) : rr(17, 52),
      });
    }
  });
  return out;
}
function initClanHeads(c) {
  const out = {};
  const all = WARRING_CLANS.concat([c.clan]).filter((x, i, a) => x && x !== "Civilian-born" && a.indexOf(x) === i);
  all.forEach((cl2) => {
    /* nobody heads the Otsutsuki. Naming a "Kenji Otsutsuki" to sit at the top
       of a house that has four members in all of history read as a joke. */
    if (cl2 === CELESTIAL) return;
    const cn = canonHead(c, cl2);
    out[cl2] = cn ? NAMED[cn].name : givenName(Math.random() < 0.5 ? "m" : "f") + " " + cl2;
  });
  return out;
}
const liveClans = (c) => WARRING_CLANS.filter((x) => !(c.extinct || []).includes(x) && !(c.broken || []).includes(x));
/* the clans people actually remember were led by people people actually remember.
   windows are by year, and a canon head only holds the seat while alive and while the era fits. */
const CANON_HEADS = {
  Uchiha: [{ id: "tajima", to: 866 }, { id: "madara", to: 926 }],
  Senju: [{ id: "butsuma", to: 866 }, { id: "hashirama", to: 926 }],
  Shimura: [{ id: "danzo", from: 940, to: 1010 }],
  Sabaku: [{ id: "rasa", from: 1010, to: 1040 }],
};
/* the canon head for a clan right now, or null if the seat is held by an ordinary name */
function canonHead(c, clan) {
  const rows = CANON_HEADS[clan];
  if (!rows) return null;
  for (const r of rows) {
    if (c.year < (r.from || 0) || c.year > (r.to || 9999)) continue;
    if (isDead(c, r.id) || !NAMED[r.id]) continue;
    if (c.deadFolk && c.deadFolk.includes(NAMED[r.id].name)) continue;
    return r.id;
  }
  return null;
}
const headIdOf = (c, clan) => canonHead(c, clan);
/* is the name currently on file for this house somebody the world has buried? */
const headIsGone = (c, name) => {
  if (!name) return true;
  if ((c.deadFolk || []).includes(name)) return true;
  return (c.dead || []).some((id) => NAMED[id] && NAMED[id].name === name);
};
const headOf = (c, clan) => {
  if (!clan || clan === "Civilian-born") return "nobody in particular";
  if (!c.clanHeads) c.clanHeads = {};
  const cn = canonHead(c, clan);
  if (cn) { c.clanHeads[clan] = NAMED[cn].name; return c.clanHeads[clan]; }
  /* a dead head is a dead head, whether they were a name out of the histories or not */
  if (headIsGone(c, c.clanHeads[clan])) c.clanHeads[clan] = freshName(c, clan);
  return c.clanHeads[clan];
};
/* and the house says so out loud when it happens */
/* a great war is not a headline you read — your village is in it and so are you */
function greatWarTick(c, L) {
  const g = greatWarAt(c.year);
  if (c.world) {
    c.world.greatFought = GREAT_WARS.filter((x) => c.year > x.to).length;
    c.world.greatNow = g ? 1 : 0;
  }
  if (!g) { if (c.greatWar) { const done = c.greatWar; c.greatWar = null; if (c.war && c.war.great) c.war = null;
      P(L, "The " + (ORDINALS[done.no - 1] || "") + " Great Ninja War is over. Whatever it was about, nobody is saying it out loud any more.", "e"); } return; }
  if (c.greatWar && c.greatWar.no === g.no) {
    /* already registered for this great war — but somebody who was too young to be
       posted when it opened does not get to sit the rest of it out just because the
       enrolment check only used to run on the opening tick. it comes for them too,
       the year they turn 12, same as the war promised. */
    if (c.greatWar.side >= 0 && !c.greatWar.enrolled && c.age >= 12 && !c.war) {
      const mine2 = c.village;
      const rawFoes2 = g.all ? g.all.filter((k) => k !== mine2) : (g.sides[1 - c.greatWar.side] || []);
      const vFoes2 = rawFoes2.filter((k) => k !== "akatsuki");
      const foes2 = vFoes2.length ? vFoes2 : rawFoes2;
      const mates2 = (g.all ? [] : (g.sides[c.greatWar.side] || [])).filter((k) => k !== mine2 && k !== "akatsuki");
      P(L, "You are " + c.age + " now. The " + (ORDINALS[g.no - 1] || "") + " Great Ninja War still needs bodies, and yours is one of them. You have been posted to a front.", "e");
      beginWar(c, L, foes2.length ? foes2 : null, true, mates2);
      if (c.war) { c.war.great = true; c.war.no = g.no; }
      c.greatWar.enrolled = true;
    }
    return;
  }
  const mine = c.village;
  const inIt = g.all ? g.all.includes(mine) : (g.sides || []).some((sd) => sd.includes(mine));
  const side = g.all ? (inIt ? 0 : -1) : (g.sides || []).findIndex((sd) => sd.includes(mine));
  c.greatWar = { no: g.no, side, from: g.from, to: g.to, all: !!g.all, enrolled: false };
  if (side < 0) {
    P(L, "The " + (ORDINALS[g.no - 1] || "") + " Great Ninja War has opened and " + (villageExists(c, mine) ? vName2(mine) : "your country") + " is not in it. That will last as long as it is useful to somebody.", "n");
    return;
  }
  const rawFoes = g.all ? g.all.filter((k) => k !== mine) : (g.sides[1 - side] || []);
  /* The Fourth is the five nations against the Akatsuki, so stripping the
     Akatsuki out left the war with no enemy in it at all and the declaration
     read "against , and everybody who can hold a kunai is in it". Only drop
     them when there is somebody else on that side to fight. */
  const villageFoes = rawFoes.filter((k) => k !== "akatsuki");
  const foes = villageFoes.length ? villageFoes : rawFoes;
  /* who is standing on YOUR side of it. This was never read, so every canon
     great war announced itself as your village alone against a coalition. */
  const mates = (g.all ? [] : (g.sides[side] || [])).filter((k) => k !== mine && k !== "akatsuki");
  const nameOf = (k) => k === "akatsuki" ? "the Akatsuki" : vName2(k);
  const ourSide = mates.length ? vName2(mine) + " and " + joinList(mates.map(nameOf)) : vName2(mine);
  P(L, "The " + (ORDINALS[g.no - 1] || "") + " Great Ninja War. " + (g.all
      ? "Every great nation against every other \u2014 " + vName2(mine) + " against " + joinList(foes.map(nameOf)) + ", and none of them against each other any less."
      : ourSide + " against " + joinList(foes.map(nameOf)) + ", and everybody who can hold a kunai is in it.")
    + (c.age < 12 ? " You are " + c.age + ". They will come for your year eventually." : " You have been posted to a front."), "e");
  if (c.age >= 12 && !c.war) {
    beginWar(c, L, foes.length ? foes : null, true, mates);
    if (c.war) { c.war.great = true; c.war.no = g.no; }
    c.greatWar.enrolled = true;
  }
}
function clanHeadTick(c, L) {
  if (!c.clanHeads) return;
  Object.keys(c.clanHeads).forEach((clan) => {
    const was = c.clanHeads[clan];
    if (!headIsGone(c, was)) return;
    const now = headOf(c, clan);
    if (now && now !== was) {
      newsItem(c, now + " has taken the " + clan + " after " + was + ". The house did not put it to a vote.", "THE VILLAGES", clan === c.clan);
      if (clan === c.clan) P(L, was + " is gone and " + now + " holds the " + clan + " now.", "n");
    }
  });
}

function makeCouncil() {
  return COUNCIL_ROLES.map((r) => ({ name: randName(Math.random() < 0.5 ? "m" : "f"), role: r, loyalty: rr(45, 78), stance: pick(COUNCIL_STANCE) }));
}
function initVillage(c, name, kageWord) {
  if (c.vil) return;
  c.vil = {
    name, kageWord, gen: 1, treasury: rr(250000, 600000), morale: 62, defense: 58, prosperity: 55,
    shinobi: rr(320, 760), decrees: [], council: makeCouncil(), history: [], reignStart: c.age,
  };
}
const councilLoyalty = (v) => (v && v.council.length ? Math.round(v.council.reduce((a, m) => a + m.loyalty, 0) / v.council.length) : 0);
const kageTitleFor = (v, gen) => (ORDINALS[(gen || v.gen) - 1] || "Latest") + " " + v.kageWord;

