const canPursue = (c, l) => { try { return l.req(c); } catch (e) { return false; } };

/* categories, for the battle menu and the jutsu list */
function moveCat(m) {
  if (!m) return { t: "Technique", c: "#aab3c0" };
  if (m.tier >= 6) return { t: "LEGENDARY", c: "#dCA84a" };
  if (m.kind === "heal") return { t: "Healing", c: "#63b972" };
  if (m.kind === "buff") return { t: m.eff === "sage" || m.eff === "baryon" ? "Transformation" : m.eff === "def" ? "Defence" : m.eff === "evade" ? "Evasion" : "Support", c: "#4a8fd6" };
  if (m.kind === "gen") return { t: "Illusion", c: "#b47fe0" };
  if (m.kind === "tai") return { t: "Taijutsu", c: "#d8624f" };
  return { t: "Ninjutsu", c: m.nature ? NC[m.nature] || "#aab3c0" : "#aab3c0" };
}

