/* ============================ HELPERS ============================ */
const R = (n) => Math.floor(Math.random() * n);
const rr = (a, b) => a + R(b - a + 1);
const pick = (a) => a[R(a.length)];
const roll = (p) => Math.random() * 100 < p;
const cl = (v, a = 0, b = 100) => Math.max(a, Math.min(b, v));
const clone = (o) => JSON.parse(JSON.stringify(o));
const money = (n) => "\u00A5" + Math.round(n).toLocaleString();
const randName = (g) => (g === "f" ? pick(F_NAMES) : pick(M_NAMES)) + " " + pick(SURNAMES);
const givenName = (g, avoid) => {
  const pool = (g === "f" ? F_NAMES : M_NAMES).filter((n) => !avoid || !avoid.includes(n));
  return pick(pool.length ? pool : g === "f" ? F_NAMES : M_NAMES);
};
const takenGiven = (c) => [c.name.split(" ")[0]].concat((c.kids || []).map((k) => k.name.split(" ")[0])).concat(c.spouse ? [c.spouse.name.split(" ")[0]] : []);
/* born into a clan means you carry its name */
const bornName = (g, clan) => givenName(g) + " " + (clan && clan !== "Civilian-born" ? clan : pick(SURNAMES));
const familyName = (c) => c.name.split(" ").slice(-1)[0];

const STAT_KEYS = [["nin", "Ninjutsu"], ["tai", "Taijutsu"], ["gen", "Genjutsu"], ["cha", "Chakra"], ["con", "Control"], ["spd", "Speed"], ["str", "Strength"], ["int", "Intellect"]];
const RANKS = ["Civilian", "Academy Student", "Genin", "Chunin", "Jonin", "Jonin Commander", "Kage"];

function power(c) {
  const s = c.stats;
  let p = s.nin * 0.17 + s.tai * 0.16 + s.gen * 0.09 + s.cha * 0.14 + s.con * 0.12 + s.spd * 0.14 + s.str * 0.08 + s.int * 0.1;
  if (c.kg) p *= 1.1;
  if (c.clan === "Otsutsuki") p *= 1.5;
  if (c.beast) p *= 1 + (c.beast.stage || 0) * 0.07;
  if (c.sage) p *= 1.15;
  if (c.sixPaths) p *= 1.25;
  if (c.eye) p *= c.eye.rinnegan ? 1.3 : c.eye.eternal ? 1.2 : c.eye.mangekyo ? 1.15 : c.eye.lv >= 3 ? 1.08 : 1;
  if (c.gates) p *= 1 + c.gates * 0.035;
  if (c.curse) p *= 1 + c.curse * 0.08;
  p += Math.min(14, (c.jutsu || []).length * 0.45);
  /* You cannot be Kage-grade at nineteen. Raw numbers get you most of the way; the last
     stretch is years in the field, and nothing else substitutes for it. */
  const yrs = Math.max(0, (c.age || 0) - 12);
  const seasoning = Math.min(1, yrs / 26) * 0.55 + Math.min(1, (c.missions || 0) / 60) * 0.25 + Math.min(1, (c.wins || 0) / 40) * 0.20;
  /* an Otsutsuki does not grow into power the way a shinobi does — they are already most
     of the way there at birth, and simply widen the gap with a career on top of it. */
  const ceiling = (c.clan === "Otsutsuki" ? 72 : 42) + seasoning * 58;            /* 42 at twelve, ~100 after a full career; 72 for an Otsutsuki */
  if (p > ceiling) p = ceiling + (p - ceiling) * 0.28;
  return Math.round(p);
}
const gearVal = (c, k) => (c.gear.weapon ? c.gear.weapon.v[k] || 0 : 0) + (c.gear.armor ? c.gear.armor.v[k] || 0 : 0);
const maxHP = (c) => Math.round(90 + c.stats.str * 1.4 + c.stats.cha * 1.0 + c.rank * 14 + gearVal(c, "hp"));
const maxCK = (c) => Math.round(45 + c.stats.cha * 1.4 + c.stats.con * 0.5);

function newChar(name, gender, vid, clanName, eraId, otsuEye) {
  const v = VILLAGES.find((x) => x.id === vid);
  let clan;
  if (clanName === "__random") {
    const pool = CLANS.filter((x) => x.v === vid);
    clan = roll(62) && pool.length ? pick(pool) : CLANS.find((x) => x.n === "Civilian-born");
  } else clan = CLANS.find((x) => x.n === clanName) || CLANS.find((x) => x.n === "Civilian-born");

  const stats = {};
  STAT_KEYS.forEach(([k]) => (stats[k] = rr(8, 20)));
  Object.keys(clan.b).forEach((k) => (stats[k] = cl(stats[k] + clan.b[k])));
  const members = {};
  const chosenClan = clanName && clanName !== "__random";
  const kgOdds = clan.kg === "Wood Release" ? (chosenClan ? 60 : 22) : chosenClan ? 100 : 78;
  let kg = clan.kg && roll(kgOdds) ? clan.kg : null;
  let eye = null;
  if (kg === "Sharingan") eye = { t: "Sharingan", lv: 0, mangekyo: false, eternal: false, rinnegan: false, blind: 0 };
  if (kg === "Byakugan") eye = { t: "Byakugan", lv: 1, mangekyo: false, eternal: false, tenseigan: false, blind: 0 };
  /* the Otsutsuki are not shinobi — they choose which eye opens rather than roll for one,
     and whichever they choose, it opens fully matured rather than green. Byakugan is the
     one every one of them carries by default. */
  let otsuEyePaths = [], otsuBonusJutsu = [], otsuChakra = 0;
  if (clan.n === "Otsutsuki") {
    const choice = otsuEye === "sharingan" ? "sharingan" : otsuEye === "rinnegan" ? "rinnegan" : "byakugan";
    otsuChakra = rr(15, 25);
    if (choice === "sharingan") {
      kg = "Sharingan";
      eye = { t: "Sharingan", lv: 3, mangekyo: false, eternal: false, rinnegan: false, blind: 0 };
      stats.gen = cl(stats.gen + 21);
      otsuBonusJutsu = ["Copy Wheel Eye"];
    } else if (choice === "rinnegan") {
      kg = "Rinnegan";
      eye = { t: "Rinnegan", lv: 3, mangekyo: true, rinnegan: true, paths: ["deva"], blind: 0 };
      stats.nin = cl(stats.nin + 18); stats.cha = cl(stats.cha + 14); stats.int = cl(stats.int + 10);
      otsuEyePaths = ["rinnegan"];
      otsuBonusJutsu = ["Almighty Push", "Universal Pull", "Preta Path Absorption"];
    } else {
      kg = "Byakugan";
      eye = { t: "Byakugan", lv: 3, mangekyo: false, eternal: false, tenseigan: false, blind: 0 };
      stats.int = cl(stats.int + 8); stats.spd = cl(stats.spd + 6);
      otsuEyePaths = ["byakugan"];
      otsuBonusJutsu = ["Gentle Fist", "Eight Trigrams Palm Rotation", "Eight Trigrams Sixty-Four Palms", "Eight Trigrams Vacuum Palm"];
    }
  }
  if (clan.n !== "Civilian-born") members[clan.n] = buildClanMembers(clan.n);
  const local = BEASTS.filter((b) => b.v === vid);
  const eraStart = (TIMELINE.find((t) => t.id === (eraId || "naruto")) || { from: 890 }).from;
  let beast = null;
  if (eraStart >= 927 && local.length && roll(7)) { const b = pick(local); beast = { id: b.id, name: b.name, tails: b.tails, nat: b.nat, stage: 0, rel: 0 }; }

  return {
    name: name || bornName(gender, clan.n), gender, village: vid, land: v.land, clan: clan.n, kg, eye, beast, era: eraId || "naruto",
    age: 0, rank: 0, rankName: (ERAS.find((e) => e.id === (eraId || "naruto")).ranks || RANKS)[0], specialty: null, natures: [], summon: null, sage: false, sageType: null,
    sixPaths: false, gates: 0, curse: 0, stats, health: 100, standing: 50, infamy: 0, ryo: rr(4000, 12000),
    jutsu: otsuBonusJutsu.slice(), otsu: otsuChakra, eyePaths: otsuEyePaths,
    titles: [], missions: 0, sMissions: 0, kills: 0, wins: 0, beastsSealed: [],
    dutyLog: {}, scouted: 0, summit: null, summitOpen: null, bench: null, booked: [],
    rogue: false, bingo: null, akatsuki: false, partner: null,
    team: null, sensei: null, rival: null, crush: null, spouse: null, kids: [],
    sibling: roll(55) ? { name: bornName(roll(50) ? "m" : "f", clan.n), alive: true } : null,
    parents: { f: { name: bornName("m", clan.n), alive: true }, m: { name: givenName("f") + " " + (clan.n !== "Civilian-born" ? clan.n : pick(SURNAMES)), alive: true } },
    actions: 4, examCooldown: 0, chuninYears: 0, joninYears: 0, warYears: 0,
    gear: { weapon: null, armor: null }, perks: [], items: {}, guardBattles: 0,
    cheats: { god: false, infActions: false, oneShot: false },
    coalition: [], founded: null, pending: null, alive: true, cause: null, gradFails: 0,
    war: null, warTitles: [], defeated: [], pendingAmbush: null, mastery: {}, raid: null, destroyed: [], lineage: [], spoils: null,
    kages: {},
    rule: { built: [], allies: [], apprentice: null, successor: null },
    vdamage: {}, canRaze: [], razed: [], bounties: [],
    dead: [], reanimated: [], news: [], anbu: null, vil: null, retired: false, world: null,
    birthYear: 0, year: 0, line: {}, daimyo: {}, clanHeads: {}, broken: [], extinct: [], hunted: {}, clanMembers: members,
    roster: (ERAS.find((e) => e.id === (eraId || "naruto")).roster || []).slice(),
  };
}

function P(L, txt, k = "n") { L.push({ txt, k }); }
function learn(c, L, name, why) { if (c.jutsu.includes(name)) return false; c.jutsu.push(name); P(L, why || "Learned " + name + ".", "e"); return true; }

/* how many natures this person can hold. most shinobi manage two, a strong jonin three.
   the ones the histories call complete — the Professor, the Copy Ninja — learn all five. */
function natureCap(c) {
  if (c.polymath) return 5;
  if (c.rank >= 6) return 4;
  if (c.rank >= 4) return 3;
  return 2;
}
/* take a new nature by working at it rather than by being handed one */
function trainNature(c, L) {
  const cap = natureCap(c);
  const base = NATURES.filter((n) => !c.natures.includes(n));
  if (!base.length) { P(L, "There are no basic natures left to take. You hold all five.", "n"); return; }
  const held = c.natures.filter((n) => NATURES.includes(n)).length;
  if (held >= cap) {
    P(L, "You cannot hold another. " + (c.polymath ? "Even you have a ceiling and this is it." : "Two comes naturally, three with rank, and beyond that you would have to be somebody the histories call complete."), "b");
    return;
  }
  /* each one after the first is markedly harder than the last — the fourth and fifth
     are the work of a decade, which is why so few names in the records hold them */
  const odds = cl(20 + c.stats.nin * 0.30 + c.stats.cha * 0.22 + c.stats.int * 0.12 - held * 20 + (c.polymath ? 15 : 0), 5, 84);
  if (roll(odds)) {
    const n = pick(base);
    c.natures.push(n);
    c.stats.nin = cl(c.stats.nin + rr(2, 5));
    P(L, "It took the whole year and it took. " + n + " Release is yours — that is " + (held + 1) + " natures now, and most people never get past one.", "e");
    if (held + 1 >= 5) {
      addTitle(c, "Master of Five Natures");
      newsItem(c, c.name + " is being called complete. All five nature transformations, held by one person, which almost nobody in the records has managed.", "BINGO BOOK", true);
      P(L, "All five. There is a very short list of people who have done this and everybody on it is remembered.", "e");
    } else if (held + 1 >= 3) {
      newsItem(c, c.name + " of " + (c.founded ? c.founded.name : vName2(c.village)) + " is fielding a third nature. The tower has taken an interest.", "THE VILLAGES");
    }
  } else {
    c.health = cl(c.health - rr(2, 6));
    P(L, pick([
      "A year of leaves that would not cut and water that would not climb. The nature did not take.",
      "You burned through the exercises and got nothing back but a headache that lasted into autumn.",
      "Close, twice. Both times it slipped. Nature transformation does not care how hard you tried.",
    ]), "b");
  }
}
function assignNature(c, L) {
  const v = VILLAGES.find((x) => x.id === c.village);
  const bag = [...NATURES, v.bias, v.bias];
  const n = pick(bag.filter((x) => !c.natures.includes(x)));
  if (n) { c.natures.push(n); P(L, "The chakra paper reacts. Your nature is " + n + " Release.", "e"); }
  if (c.kg && ADVANCED.includes(c.kg) && !c.natures.includes(c.kg)) { c.natures.push(c.kg); P(L, "Your bloodline burns through: " + c.kg + " awakens alongside it.", "e"); }
}
function makeTeam(c, L) {
  const t = [];
  for (let i = 0; i < 2; i++) { const g = roll(50) ? "m" : "f"; t.push({ name: randName(g), gender: g, per: pick(PERS), rel: rr(45, 68), alive: true }); }
  c.team = t;
  c.sensei = { name: randName(roll(50) ? "m" : "f"), per: pick(PERS), rel: rr(45, 62), alive: true };
  P(L, TT(c, "squad") + " assignment: you, " + t[0].name + " (" + t[0].per + ") and " + t[1].name + " (" + t[1].per + ").", "g");
  P(L, "Your " + TT(c, "sensei") + " is " + c.sensei.name + ", " + c.sensei.per + " and unimpressed so far.", "g");
}
function loss(c, L, who) {
  c.lostSomeone = (c.lostSomeone || 0) + 1;
  if (c.eye && c.eye.t === "Sharingan" && c.eye.lv >= 3 && !c.eye.mangekyo) {
    c.eye.mangekyo = true;
    ["Amaterasu", "Tsukuyomi", "Susanoo"].forEach((j) => learn(c, L, j));
    P(L, "Watching " + who + " die broke something behind your eyes. The Mangekyo Sharingan awakened.", "e");
  }
}

/* ============================ COMBAT ENGINE ============================ */
/* ============================ COMBAT CORE (v10 tactical) ============================ */
/* Range: close (tai dominant), mid (balanced / ninjutsu sweet spot), far (ninjutsu & ranged)
   Momentum: the aggressor who keeps landing hits gains pressure; the one on the back foot pays for it.
   Specialty: your chosen path warps the numbers and the language.
   Hand seals: forming them is a quick-time sequence resolved on the spot, in the same turn
   you spend casting — not a multi-turn commitment that leaves you eating free hits while you
   build it. Accuracy on the sequence scales the technique's power instead of making it. */
const RANGE_LABEL = { close: "Close range", mid: "Mid range", far: "Long range" };
/* the twelve seals, same order the histories use */
const HAND_SEALS = [
  { id: "rat", n: "Rat" }, { id: "ox", n: "Ox" }, { id: "tiger", n: "Tiger" }, { id: "hare", n: "Hare" },
  { id: "dragon", n: "Dragon" }, { id: "snake", n: "Snake" }, { id: "horse", n: "Horse" }, { id: "ram", n: "Ram" },
  { id: "monkey", n: "Monkey" }, { id: "bird", n: "Bird" }, { id: "dog", n: "Dog" }, { id: "boar", n: "Boar" },
];
const SPEC_COMBAT = {
  nin:  { tai: 0.85, nin: 1.25, gen: 0.9,  label: "ninjutsu specialist" },
  tai:  { tai: 1.30, nin: 0.80, gen: 0.75, label: "taijutsu specialist" },
  gen:  { tai: 0.75, nin: 0.90, gen: 1.35, label: "genjutsu specialist" },
  med:  { tai: 0.90, nin: 0.95, gen: 0.95, label: "medical-nin" },
  sen:  { tai: 0.90, nin: 1.05, gen: 1.10, label: "sensor-nin" },
  sum:  { tai: 0.95, nin: 1.10, gen: 0.90, label: "summoner" },
  fuin: { tai: 0.85, nin: 1.15, gen: 1.05, label: "fuinjutsu master" },
  ken:  { tai: 1.20, nin: 0.90, gen: 0.80, label: "kenjutsu specialist" },
  pup:  { tai: 0.95, nin: 1.10, gen: 0.95, label: "puppet master" },
  wep:  { tai: 1.15, nin: 0.95, gen: 0.85, label: "weapons specialist" },
};
function playerFighter(c) {
  const s = c.stats;
  const spec = SPEC_COMBAT[c.specialty] || { tai: 1, nin: 1, gen: 1 };
  return {
    side: "p", name: c.name, doujutsu: !!(c.eye && c.eye.t),
    hp: maxHP(c), max: maxHP(c), ck: maxCK(c), ckMax: maxCK(c),
    atk: Math.round((s.tai * 0.85 + s.str * 0.5 + gearVal(c, "atk")) * (spec.tai || 1)),
    nin: Math.round((s.nin * 0.9 + s.cha * 0.35) * (spec.nin || 1)),
    gen: Math.round((s.gen * 0.9 + s.int * 0.4) * (spec.gen || 1)),
    def: Math.round((s.str + s.tai) * 0.3 + c.rank * 2 + gearVal(c, "def")),
    eva: Math.round(s.spd * 0.42 + s.int * 0.12),
    spd: s.spd, nature: c.natures[0] || null, specialty: c.specialty || null,
    fx: { evade: 0, atk: 0, def: 0, stun: 0, burn: 0, acc: 0, sage: 0, baryon: 0, held: 0 },
    form: null, formLeft: 0, weak: 0, charging: null, chargeLeft: 0, weaving: null,
    manual: c.perks.includes("manual"), range: "mid", momentum: 0,
  };
}
function enemyFighter(tpl, scale, weakened, forced, preVillage) {
  const l = tpl.lvl * scale * (weakened ? 0.9 : 1);
  const nm = forced && forced.name ? forced.name : tpl.named ? tpl.name : randName(Math.random() < 0.5 ? "m" : "f");
  const ti = forced && forced.title ? forced.title : tpl.named ? tpl.title : preVillage ? ERA_ENEMY_TITLE[tpl.name] || tpl.name : tpl.name;
  const hp = Math.round(l * 6.2);
  const atk = Math.round(l * 1.45);
  return {
    side: "e", name: nm, title: ti, desc: tpl.desc, lvl: Math.round(l),
    doujutsu: /sharingan|byakugan|rinnegan|uchiha|hyuga/i.test((tpl.desc || "") + " " + (tpl.name || "") + " " + (tpl.nature || "")),
    hp, max: hp, ck: 999, ckMax: 999,
    atk, nin: atk, gen: Math.round(atk * 0.8), def: Math.round(l * 0.4),
    eva: Math.round(tpl.spd * 0.4), spd: tpl.spd || 20, nature: tpl.nature,
    moves: tpl.moves.map((m) => [m[0], Math.round(atk * m[1]), m[2]]),
    fx: { evade: 0, atk: 0, def: 0, stun: 0, burn: 0, acc: 0, sage: 0, baryon: 0, held: 0 },
    form: null, formLeft: 0, weak: 0, charging: null, chargeLeft: 0, weaving: null,
    range: "mid", momentum: 0,
  };
}

/* colour + glow for whatever nature is standing across from you — used to tint the pre-fight
   face-off and the ambient frame around a fight worth remembering. unmatched natures fall back
   to blood red rather than grey, so nothing renders as a colourless nobody. */
const NATURE_FX = {
  Fire: "#e2683f", "Lava Release": "#e2683f", "Scorch Release": "#e2683f", "Explosion Release": "#e2b24a",
  Water: "#4f97c9", "Storm Release": "#4f97c9", "Boil Release": "#7fb8c9",
  Wind: "#8fd6b0", Earth: "#b8874a", "Dust Release": "#b8874a", "Wood Release": "#7fa85a",
  Lightning: "#c9a8f0", Chakra: "#cf4232", Ice: "#9fd8e8",
};
const natureFx = (nature) => NATURE_FX[nature] || "#cf4232";
function natMult(atkNat, defNat) {
  if (!atkNat || !defNat) return 1;
  if (BEATS[atkNat] === defNat) return 1.42;
  if (BEATS[defNat] === atkNat) return 0.68;
  return 1;
}
function rangeMult(kind, range) {
  if (kind === "tai" || kind === "ken" || kind === "wep") return range === "close" ? 1.28 : range === "mid" ? 1.0 : 0.62;
  if (kind === "nin") return range === "far" ? 1.18 : range === "mid" ? 1.08 : 0.82;
  if (kind === "gen") return range === "close" ? 0.88 : 1.12;
  return 1;
}
function calcDmg(a, d, kind, pow, nature, pierce) {
  const stat = kind === "tai" || kind === "ken" || kind === "wep" ? a.atk : kind === "gen" ? a.gen : a.nin;
  let base = (pow * 0.52 + stat * 0.72) * (0.86 + Math.random() * 0.28);
  base *= natMult(nature, d.nature);
  base *= rangeMult(kind, a.range || "mid");
  /* momentum: the one pressing the fight hits harder */
  base *= 1 + Math.max(-0.18, Math.min(0.28, (a.momentum || 0) * 0.04));
  const fm = a.form && FORMS[a.form] ? FORMS[a.form] : null;
  base *= 1 + (a.fx.atk || 0) * 0.30;
  if (fm) base *= fm.atk;
  if (a.weak > 0) base *= 0.58;
  const dfm = d.form && FORMS[d.form] ? FORMS[d.form] : null;
  if (dfm) base /= dfm.def;
  if (a.manual) base *= 1.18;
  if (kind === "gen") {
    base *= 1.40;
    base *= 100 / (100 + (d.gen || 0) * 0.95);
    base *= 1 + (d.fx.held || 0) * 0.32;
    if (d.doujutsu) base *= 0.50;
    return Math.max(2, Math.round(base));
  }
  const armour = d.def * (1 + (d.fx.def || 0) * 0.58) * (pierce ? 0.88 : 2.25);
  base *= 100 / (100 + armour);
  return Math.max(3, Math.round(base));
}
function genHold(att, def, log) {
  def.fx.held = (def.fx.held || 0) + 1;
  const deep = def.fx.held;
  if (log) log.push({ t: deep === 1
    ? def.name + " blinks and the world slips. They are still moving, but at something that is no longer there."
    : deep === 2
    ? def.name + " is two layers under. Their eyes track shadows that only they can see."
    : def.name + " is " + deep + " layers deep. Nothing they are fighting has ever been real.", k: def.side === "p" ? "b" : "g" });
  if (deep >= 2 && roll(28 + deep * 14)) {
    def.fx.stun = Math.max(def.fx.stun || 0, 1);
    if (log) log.push({ t: def.name + " freezes mid-step. The illusion has them completely.", k: def.side === "p" ? "b" : "g" });
  }
}
function genBreak(f, log) {
  if (!f.fx.held) return false;
  const own = (f.gen || 0) * 0.55 + 20 + (f.doujutsu ? 25 : 0);
  if (roll(own)) {
    f.fx.held = 0;
    if (log) log.push({ t: f.name + " forces the chakra still, then restarts it. The world snaps back into place, raw and too bright.", k: f.side === "p" ? "g" : "b" });
    return true;
  }
  if (log) log.push({ t: f.name + " reaches for the edge of the illusion and finds only more of it.", k: f.side === "p" ? "b" : "g" });
  return false;
}
function tryHit(a, d, log) {
  if (d.fx.evade > 0) {
    d.fx.evade = 0;
    const seen = cl(((d.evadeUses || 1) - 1) * 26 + (a.fx.acc > 0 ? 22 : 0), 0, 80);
    if (roll(seen)) {
      if (log) log.push({ t: a.name + " had already read the substitution. The strike lands where " + d.name + " was going to be.", k: a.side === "p" ? "g" : "b" });
      return true;
    }
    if (log) log.push({ t: d.name + " is gone. A log takes the hit and splits.", k: d.side === "p" ? "g" : "b" });
    return false;
  }
  /* range affects accuracy slightly — taijutsu at far range is harder to land clean */
  let miss = cl(d.eva * 0.52 - (a.fx.acc || 0) * 13 - (a.side === "p" ? 3 : 0), 2, 40);
  if ((a.range === "far") && (["tai", "ken", "wep"].includes(a._lastKind))) miss += 12;
  if ((a.range === "close") && a._lastKind === "nin") miss += 6;
  return !roll(miss);
}
function tickFx(f, log) {
  ["atk", "def", "stun", "acc", "sage"].forEach((k) => { if (f.fx[k] > 0) f.fx[k] -= 1; });
  if (f.weak > 0) f.weak -= 1;
  if (f.form) {
    const fm = FORMS[f.form];
    f.formLeft -= 1;
    if (fm.upkeep) f.ck = Math.max(0, (f.ck || 0) - fm.upkeep);
    if (fm.hpTick) {
      f.hp -= fm.hpTick;
      if (log) log.push({ t: f.name + " holds the form and pays for it in flesh. −" + fm.hpTick + " HP.", k: f.side === "p" ? "b" : "g" });
    }
    const outOfChakra = fm.upkeep && (f.ck || 0) <= 0;
    if (f.formLeft <= 0 || outOfChakra) {
      const ex = fm.exhaust || {};
      f.form = null;
      f.weak = ex.turnsWeak || 2;
      if (ex.hp) f.hp -= ex.hp;
      if (log) log.push({ t: outOfChakra
        ? f.name + " runs dry. The form collapses and leaves them shaking, everything after this at two-thirds strength."
        : f.name + " can no longer hold it. The power drains out and the cost remains.", k: f.side === "p" ? "b" : "g" });
    }
  }
  if (f.charging) f.chargeLeft -= 1;
  if (f.cools) Object.keys(f.cools).forEach((k) => { if (f.cools[k] > 0) f.cools[k] -= 1; });
  if (f.fx.held > 0) {
    const bleed = 7 + f.fx.held * 6;
    f.hp -= bleed;
    if (log) log.push({ t: f.name + " is still trapped inside it. " + bleed + " damage from a fight that is not happening.", k: f.side === "p" ? "b" : "g" });
    if (roll(16 + (f.gen || 0) * 0.38 + (f.doujutsu ? 32 : 0))) {
      f.fx.held = 0;
      if (log) log.push({ t: f.name + " finds the seam and tears free. Reality rushes back in.", k: f.side === "p" ? "g" : "b" });
    }
  }
  if (f.fx.evade > 0) f.fx.evade -= 1;
  if (f.fx.baryon > 0) {
    f.fx.baryon -= 1;
    const d = Math.round(f.max * 0.08);
    f.hp = Math.max(1, f.hp - d);
    if (log) log.push({ t: f.name + " burns lifespan as fuel. −" + d + " HP. The air itself feels thinner.", k: "b" });
  }
  if (f.fx.burn > 0) {
    const d = 14;
    f.hp -= d;
    f.fx.burn -= 1;
    if (log) log.push({ t: "Black flame continues to eat at " + f.name + ". −" + d + ".", k: "b" });
  }
  /* momentum slowly decays toward neutral if nobody is pressing */
  if (f.momentum > 0) f.momentum = Math.max(0, f.momentum - 0.35);
  if (f.momentum < 0) f.momentum = Math.min(0, f.momentum + 0.35);
}

