/* ============================ PEOPLE ============================ */
/* relationships were a number. now they have a state, they drift when neglected,
   and they do things on their own. */
const REL_STATES = [
  { at: 0,  n: "estranged", d: "does not seek you out any more" },
  { at: 20, n: "cool", d: "civil, and nothing past that" },
  { at: 40, n: "steady", d: "you can rely on them for what you would ask anybody" },
  { at: 62, n: "close", d: "would go out of their way, and has" },
  { at: 80, n: "would die for you", d: "and both of you know it, and neither says it" },
];
const relState = (v) => REL_STATES.filter((r) => (v || 0) >= r.at).pop() || REL_STATES[0];
function relationTick(c, L) {
  const drift = (o, floor) => { if (!o) return; if (o.rel === undefined) return; if (roll(45)) o.rel = cl(o.rel - rr(1, 3), floor || 0, 100); };
  /* people you do not see drift. it is not personal and that is the problem. */
  (c.team || []).forEach((t) => { if (t.alive) drift(t, 0); });
  if (c.sensei && c.sensei.alive) drift(c.sensei, 0);
  if (c.spouse) { if (roll(30)) c.spouse.rel = cl(c.spouse.rel + (c.age > 40 ? 1 : 0) - (c.war ? 2 : 0)); }
  (c.kids || []).forEach((k) => { if (!k.dead && roll(35)) k.bond = cl((k.bond || 50) - rr(1, 2)); });
  /* and they act on their own */
  if (roll(9)) {
    const alive = (c.team || []).filter((t) => t.alive);
    if (alive.length) {
      const t = pick(alive);
      const st = relState(t.rel);
      if (t.rel >= 70 && roll(50)) { c.health = cl(c.health + rr(3, 8)); P(L, t.name + " turned up at your door with food and did not explain why. They knew.", "g"); }
      else if (t.rel <= 22 && roll(45)) { P(L, "You have not spoken to " + t.name + " properly in two years. Neither of you has decided that, it has just happened.", "b"); }
      else if (roll(25)) P(L, pick([
        t.name + " asked you to stand at their wedding. You said yes before they finished.",
        t.name + " has started requesting the same missions you take. Neither of you has mentioned it.",
        "You and " + t.name + " got drunk and said the things people say once. Both of you were fine about it in the morning.",
      ]), "g");
    }
  }
  if (c.spouse && c.spouse.rel <= 18 && roll(12)) {
    P(L, "It ended. Not in a scene — in a series of weeks where neither of you was there, and then one of you had moved out.", "b");
    c.exes = (c.exes || []).concat([c.spouse.name]);
    c.spouse = null;
    c.health = cl(c.health - 8);
  }
  if ((c.kids || []).some((k) => k.bond <= 15 && !k.dead) && roll(10)) {
    const k = c.kids.find((x) => x.bond <= 15 && !x.dead);
    if (k && !k.estranged) { k.estranged = true; P(L, k.name + " has stopped coming by. They are old enough now to make that choice and they have made it.", "b"); }
  }
}

