/* they do not age the way people do, and the power is in the blood rather than the training */
function otsutsukiTick(c, L) {
  if (c.clan !== "Otsutsuki" && !c.karmaHost) return;
  c.otsu = (c.otsu || 0) + (c.clan === "Otsutsuki" ? rr(1, 3) : 1);
  if (c.clan === "Otsutsuki") {
    /* a century is a season to them */
    if (c.age > 30 && roll(70)) c.health = cl(c.health + rr(1, 4));
    if (c.age === 40) P(L, "You have stopped changing. Everybody who was your age is grey and you are not, and they have started to notice.", "e");
  }
  if (c.otsu === 20) P(L, "The chakra in you has stopped behaving like chakra. It does not run out the way it did.", "e");
  if (c.otsu === 45) P(L, "You can feel the tree in the ground somewhere under all this, waiting to be planted.", "e");
  if (c.karma && !c.karmaBack && !c.alive) { /* handled at death */ }
}
const otsuAvailable = (c) => c.clan === "Otsutsuki" || c.karmaHost || (c.otsu || 0) >= 20 || c.karma;

