/* ============================ THE EYES ============================ */
/* a Sharingan is not a stat. it is three tomoe, then a pattern nobody else has,
   then a price, and then — for about four people ever — something else entirely. */
const TOMOE = [
  { n: "One tomoe", d: "You are reading movement a fraction before it happens and it is exhausting.", gen: 4, acc: 1 },
  { n: "Two tomoe", d: "You can follow hand seals well enough to copy them if you are quick.", gen: 7, acc: 2 },
  { n: "Three tomoe", d: "Fully matured. Nothing done in front of you is done unseen.", gen: 10, acc: 3 },
];
/* every Mangekyo is different. yours is rolled once and it is yours. */
const MANGEKYO_POWERS = [
  { id: "black", n: "Amaterasu", d: "Black fire where you look. It does not go out and it does not stop for water.", j: "Amaterasu", cost: "blind", eff: "burn" },
  { id: "dream", n: "Tsukuyomi", d: "Three days inside a second. They come out and they are not the same person.", j: "Tsukuyomi", cost: "blind", eff: "stun" },
  { id: "avatar", n: "Susanoo", d: "A skeleton of chakra around you, then muscle, then armour, then a sword.", j: "Susanoo", cost: "strain", eff: "def" },
  { id: "warp", n: "Kamui", d: "A place that is not here, and you can put things in it. Including yourself.", j: "Kamui", cost: "strain", eff: "evade" },
  { id: "bind", n: "Kotoamatsukami", d: "One order, given so gently they will believe it was their own idea for a decade.", j: "Kotoamatsukami", cost: "long", eff: "stun" },
  { id: "chain", n: "Izanagi", d: "You can decide that the last few seconds did not happen. Once, and it costs the eye.", j: "Izanagi", cost: "eye", eff: "izanagi" },
  { id: "loop", n: "Izanami", d: "You put them in the same few seconds until they accept what they are. They stop fighting. It costs the eye.", j: "Izanami", cost: "eye", eff: "izanami" },
];
const RINNEGAN_PATHS = [
  { id: "deva", n: "Deva Path", d: "Push and pull at everything in front of you, on a count you can feel.", j: "Almighty Push" },
  { id: "asura", n: "Asura Path", d: "Your own body opens and there is machinery in it.", j: "Asura Mechanised Limb" },
  { id: "human", n: "Human Path", d: "Take a mind out through the forehead and read it. They do not survive it.", j: "Human Path: Mind Reading" },
  { id: "animal", n: "Animal Path", d: "Summon anything, anywhere, without a contract.", j: "Summoning: Rinnegan Beasts" },
  { id: "preta", n: "Preta Path", d: "Absorb any technique made of chakra, which is nearly all of them.", j: "Preta Path Absorption" },
  { id: "naraka", n: "Naraka Path", d: "The King of Hell asks a question and takes the answer out of them.", j: "Naraka Path: King of Hell" },
  { id: "outer", n: "Outer Path", d: "Bring back the dead. It costs you the years they get.", j: "Outer Path: Rinne Rebirth" },
];
[...MANGEKYO_POWERS.map((m) => ({ n: m.j, t: 6, k: "gen", p: 132, c: 46, e: m.eff })),
 ...RINNEGAN_PATHS.map((r) => ({ n: r.j, t: 6, k: "nin", p: 138, c: 48, e: null }))].forEach((m) => {
  if (!MOVES[m.n]) MOVES[m.n] = { name: m.n, tier: m.t, kind: m.k, nature: null, pow: m.p, cost: m.c, eff: m.e || null };
});
/* the eye grows on its own when the life is hard enough */
function eyeTick(c, L) {
  if (!c.eye || c.eye.t !== "Sharingan") return;
  const e = c.eye;
  if (e.lv === undefined) e.lv = 1;
  if (e.blind === undefined) e.blind = 0;
  /* tomoe come from being in real danger, not from training */
  if (e.lv < 3 && (c.wins || 0) >= e.lv * 6 && roll(30)) {
    e.lv += 1;
    const t = TOMOE[e.lv - 1];
    c.stats.gen = cl(c.stats.gen + t.gen);
    P(L, "A second thing happened behind your eyes this year. " + t.n + ". " + t.d, "e");
  }
  /* the Mangekyo does not come from winning */
  if (e.lv >= 3 && !e.mangekyo && (c.lostSomeone || 0) > 0 && roll(22)) {
    e.mangekyo = true;
    const mk = pick(MANGEKYO_POWERS);
    e.power = mk.id; e.powerName = mk.n;
    learn(c, L, mk.j, "The pattern in your eyes changed the day it happened. " + mk.n + " — " + mk.d);
    c.stats.gen = cl(c.stats.gen + 12);
    addTitle(c, "Mangekyo: " + mk.n);
    P(L, "Something in you broke and the eye answered it. No two of these are the same and this one is yours.", "e");
    c.eyeFlash = mk.n;
    newsItem(c, c.name + " has been seen with a pattern in the eyes that nobody in the clan records recognises.", "BINGO BOOK", true);
  }
  /* and it takes your sight for using it */
  if (e.mangekyo && !e.eternal && !e.rinnegan) {
    if (roll(40)) {
      e.blind = cl((e.blind || 0) + rr(2, 6));
      if (e.blind >= 40 && e.blind < 70 && roll(40)) P(L, "The edges of things have gone soft. You have started turning your head to see what you used to see straight on.", "b");
      if (e.blind >= 70) { c.stats.gen = cl(c.stats.gen - 2); if (roll(30)) P(L, "You are going blind. Everyone who has ever had these eyes went blind and you knew that when you started.", "b"); }
      if (e.blind >= 100 && !e.blindDone) { e.blindDone = true; c.stats.gen = cl(c.stats.gen - 20); addTitle(c, "Went blind"); P(L, "It is dark now. You can still fight — you have been fighting by sound for two years — but the eyes are finished.", "b"); }
    }
  }
}

