/* ============================ THE THING IN THE SEAL ============================ */
/* it is a person. it has been in cages for a thousand years and it has opinions about that. */
const BEAST_BOND = [
  { n: "Sealed", d: "It is in there and it is furious. You get chakra out of it the way you get anything out of an animal in a trap." },
  { n: "Bargaining", d: "It has started talking. Everything it says is true and everything it says is also a trade." },
  { n: "Named", d: "It told you what it is actually called. Nobody has asked it that in four hundred years." },
  { n: "Partner", d: "You fight together instead of one of you borrowing the other. The seal is still there and neither of you mentions it." },
  { n: "Complete", d: "There is no line between what you can do and what it can do. It stands behind you when you walk." },
];
const BEAST_ACTS = [
  { id: "meditate", n: "Sit down in front of the bars", d: "No demands, no chakra taken. You just go in and sit there. It hates this and it keeps talking.", rel: [6, 14] },
  { id: "pull", n: "Pull chakra out of it", d: "Faster than asking. It costs the relationship every time and it always works.", rel: [-14, -6], power: true },
  { id: "argue", n: "Argue with it about the villages", d: "It has watched every one of them lie to a child with a seal on their stomach. It is not entirely wrong.", rel: [4, 12], int: true },
  { id: "name", n: "Ask it what it is called", d: "The thing nobody asks. It will not answer until it decides you are worth answering.", rel: [10, 20], needs: 1 },
  { id: "share", n: "Offer it something of yours", d: "Not chakra. A memory, a person's name, the reason you keep going. It has never been offered anything.", rel: [12, 22], needs: 2 },
  { id: "sync", n: "Train the transformation", d: "Not borrowing the cloak. Both of you moving as one thing, which takes years and nearly kills you first.", rel: [6, 12], needs: 3, power: true },
];
const beastStageName = (c) => (c.beast ? (BEAST_BOND[Math.min(c.beast.stage || 0, 4)] || BEAST_BOND[0]).n : "");
function beastTick(c, L) {
  if (!c.beast) return;
  const b = c.beast;
  if (b.rel === undefined) b.rel = 5;
  if (b.stage === undefined) b.stage = 0;
  const bd = BEASTS.find((x) => x.id === b.id);
  /* the relationship decides the stage, not the other way round */
  const want = b.rel >= 92 ? 4 : b.rel >= 72 ? 3 : b.rel >= 48 ? 2 : b.rel >= 24 ? 1 : 0;
  if (want > b.stage) {
    b.stage = want;
    const st = BEAST_BOND[b.stage];
    P(L, "Something has changed between you and the thing in the seal. " + st.n + " — " + st.d, "e");
    if (b.stage === 2 && bd) { b.named = true; revealBeast(c, bd.id); P(L, "It told you its name. It is " + bd.name + ", and it has not heard anybody say it out loud since before the villages existed.", "e"); newsItem(c, c.name + " has been heard calling the " + bd.tails + "-Tails by a name nobody in the village has on record.", "THE BEASTS", true); }
    if (b.stage === 3) learn(c, L, "Tailed Beast Rasengan", "The two of you built something neither of you could make alone.");
    if (b.stage === 4) { addTitle(c, "Perfect Jinchuriki"); newsItem(c, c.name + " has been seen using the full cloak with the beast standing behind them and both of them moving the same way. There is no procedure for what to do about that.", "THE BEASTS", true); }
  } else if (want < b.stage && b.rel < 20) {
    b.stage = want;
    P(L, "Whatever you had built with it is gone. It is back behind the bars and it is not talking to you.", "b");
  }
  /* a bad relationship is dangerous to everybody near you */
  if (b.rel <= 15 && c.age >= 8 && roll(9)) {
    const tails = Math.min(4, 1 + Math.floor((20 - b.rel) / 6));
    c.health = cl(c.health - rr(8, 20));
    c.standing = cl(c.standing - rr(5, 14));
    c.kills += rr(0, 3);
    P(L, "You lost control. " + tails + " tails, in the middle of the village, and you do not remember any of it. They are still counting.", "b");
    newsItem(c, "Something came out of " + c.name + " in " + homeName(c) + " and " + rr(2, 14) + " people are dead. The tower is calling it an incident.", "THE BEASTS", true);
  }
}

/* ============================ WHAT THEY CALL YOU ============================ */
/* a name people use when they are not using your name. earned, never chosen. */
const EPITHETS = [
  { id: "demon", n: "the Demon of the Mist", w: (c) => c.rogue && c.kills >= 40 && c.village === "kiri", pri: 8 },
  { id: "copy", n: "the Copy Ninja", w: (c) => (c.copied || 0) >= 25, pri: 9 },
  { id: "flash", n: "the Yellow Flash", w: (c) => c.stats.spd >= 92 && c.jutsu.includes("Flying Thunder God"), pri: 9 },
  { id: "professor", n: "the Professor", w: (c) => c.natures && c.natures.length >= 5, pri: 9 },
  { id: "god", n: "the God of Shinobi", w: (c) => power(c) >= 95 && c.wins >= 40, pri: 10 },
  { id: "beastking", n: "the One Who Holds It", w: (c) => c.beast && c.beast.stage >= 4, pri: 7 },
  { id: "reaper", n: "the Reaper of the Border", w: (c) => c.kills >= 60, pri: 6 },
  { id: "ghost", n: "the Ghost", w: (c) => c.rogue && c.infamy >= 70 && (c.perks || []).includes("falseid"), pri: 7 },
  { id: "butcher", n: "the Butcher", w: (c) => (c.darkDeeds || 0) >= 6, pri: 7 },
  { id: "silent", n: "the Silent One", w: (c) => c.jutsu.includes("Silent Killing") && c.kills >= 25, pri: 6 },
  { id: "kinslayer", n: "the Kinslayer", w: (c) => c.clan !== "Civilian-born" && (c.broken || []).includes(c.clan) && c.rogue, pri: 8 },
  { id: "whitefang", n: "the White Fang", w: (c) => c.gear && c.gear.weapon && c.stats.tai >= 85 && c.wins >= 25, pri: 6 },
  { id: "sage", n: "the Sage", w: (c) => c.sage, pri: 8 },
  { id: "eyes", n: "the One With Those Eyes", w: (c) => c.eye && c.eye.mangekyo, pri: 7 },
  { id: "unkillable", n: "the Unkillable", w: (c) => c.health >= 90 && c.wins >= 30 && c.stats.con >= 85, pri: 7 },
  { id: "quiet", n: "the Quiet Death", w: (c) => c.anbu && c.kills >= 30, pri: 6 },
  { id: "bloodline", n: "the Last of Their Blood", w: (c) => c.clan !== "Civilian-born" && (c.extinct || []).includes(c.clan), pri: 8 },
  { id: "ringbearer", n: "of the Akatsuki", w: (c) => !!c.akatsuki, pri: 8 },
];
function checkEpithet(c, L) {
  const earned = EPITHETS.filter((e) => { try { return e.w(c); } catch (err) { return false; } })
    .sort((a, b) => b.pri - a.pri)[0];
  if (!earned) return;
  const isNew = !(c.epithets || []).includes(earned.n);
  if (isNew) c.epithets = (c.epithets || []).concat([earned.n]);
  /* once you have picked one yourself, the world stops overwriting it on its own —
     new ones still get earned and added to the list, just not forced on you */
  if (c.epithetPicked) {
    if (isNew) P(L, "People have started calling you something new — " + earned.n + ". You can pick it up under Profile if you want it.", "n");
    return;
  }
  if (c.epithet === earned.n) return;
  const first = !c.epithet;
  c.epithet = earned.n;
  P(L, first
    ? "People have started calling you something. " + c.name + " " + earned.n + " — you did not pick it and you cannot stop it."
    : "What they call you has changed. You are " + c.name + " " + earned.n + " now.", "e");
  newsItem(c, c.name + " is being called " + earned.n + " in three countries. Nobody has recorded who said it first.", "BINGO BOOK", true);
}

/* ---------- your own page in the book ---------- */
/* ---- names this playthrough put in the book ----
   The Bingo Book used to be a pure view of the named roster plus the era's
   bosses, so nothing in the game could ever add to it. Every line that said a
   name had been entered in it \u2014 the court's own rider, an exile walked to the
   gate, a hunter order \u2014 printed and then did nothing at all. It holds
   entries now, and they show up in the book with the reason and the bounty. */
function bookName(c, e) {
  if (!c || !e || !e.name) return false;
  if (!c.booked) c.booked = [];
  if (c.booked.some((x) => x.name === e.name)) return false;
  c.booked.push({
    name: e.name, rank: e.rank || null, tier: e.tier || "C",
    why: e.why || "listed by order of a court", year: c.year,
    by: e.by || (c.name || "the bench"), vid: c.village,
    bounty: e.bounty != null ? e.bounty : ({ S: 1200000, A: 480000, B: 160000, C: 45000 }[e.tier || "C"] || 45000),
    pw: e.pw || null, dead: false,
    from: e.from || null, age: e.age || null, named: e.named || null, kage: !!e.kage, warrant: e.warrant || null,
  });
  return true;
}
const bookedOf = (c) => ((c && c.booked) || []).filter((x) => !x.dead && !x.pardoned && !x.withdrawn);

const BINGO_TIERS = [
  { r: "C", at: 20, d: "a nuisance with a name" },
  { r: "B", at: 40, d: "approach with a squad" },
  { r: "A", at: 60, d: "approach with a jonin cell, or do not approach" },
  { r: "S", at: 80, d: "flee on sight. Do not engage. Report the direction they were going" },
];
function bingoTick(c, L) {
  if (!c.rogue && c.infamy < 30) return;
  const tier = BINGO_TIERS.filter((t) => c.infamy >= t.at).pop();
  if (!tier) return;
  if (c.bingo === tier.r) return;
  const rising = !c.bingo || BINGO_TIERS.findIndex((t) => t.r === tier.r) > BINGO_TIERS.findIndex((t) => t.r === c.bingo);
  c.bingo = tier.r;
  if (!rising) return;
  c.bounty = Math.round((30000 + c.infamy * 9000 + power(c) * 4000) / 1000) * 1000;
  P(L, "Your page in the Bingo Book has been updated to " + tier.r + "-rank. The standing order on you now reads: " + tier.d + ".", "b");
  newsItem(c, c.name + (c.epithet ? " " + c.epithet : "") + " has been raised to " + tier.r + "-rank in the Bingo Book. The bounty stands at " + money(c.bounty) + " and the entry reads: " + tier.d + ".", "BINGO BOOK", tier.r === "S" || tier.r === "A");
}

