      const odds = f.rare
        ? cl(9 + (power(c2) - 88) * 0.6 + c2.stats.int * 0.15 - (c2.forbidden || []).length * 2, 2, 35)
        : cl(24 + (power(c2) - 72) * 1.5 + c2.stats.int * 0.3 - (c2.forbidden || []).length * 6, 5, 82);
